const sphOf = (e, c) => { const o = sub(e, c), r = len(o); return [r, Math.atan2(o[0], o[2]), Math.asin(clamp(o[1] / r, -1, 1))]; };
const ease5 = t => { t = clamp(t); return t * t * t * (t * (6 * t - 15) + 10); };
// camera keys: one per step, plus holds. Step 0 stays close until the ambient sensor has plugged in, then pulls out slowly;
// the "That's Tapstr" step keeps the sensor-cluster framing (no pull-out before pushing in on the keg)
const CK = STEPS.map((st, i) => ({ p: i, cam: st.cam, sc: st.scene }));
CK.unshift({ p: -1, cam: INTRO.cam, sc: 0 }, { p: -.18, cam: [[120, 1560, 980], [190, 1570, 0], 40], sc: 0 });
const VIEWB = [[-110, 1430, -170], [252, 1572, 20], 44];
CK.splice(1, 0, { p: .2, cam: VIEWB, sc: 0 }, { p: .4, cam: VIEWB, sc: 0 });
{ const k3 = CK.find(k => k.p === 3); k3.cam = STEPS[2].cam; }
{ const k8 = CK.find(k => k.p === 8); k8.p = 8.35; }   // one long smooth zoom from the wide fridge (p 7) to the badge as the door shuts
CK.sort((x, y) => x.p - y.p);
const easeK = t => { t = clamp(t); return .38 * t + .62 * ease5(t); };   // keeps ~40% speed at the joins instead of stopping
function camAt(p) {
  p = clamp(p, -1, STEPS.length - 1);
  const base = keyCam(p), w = ss((p - .4) / .1) * (1 - ss((p - .88) / .1));
  if (w <= 0) return base;
  // follow the head of the long cable as it draws along the walls
  const P = run1.P, h = P[Math.min(P.length - 1, Math.floor((P.length - 1) * run1.grow))];
  const vp = [60, 1430, 900], dir = norm(sub(vp, h)), d = 320 + 620 * ss(clamp(run1.grow * 2.2));   // close as it leaves the hub, pulling back as it travels
  const fe = add(h, mulv(dir, d));
  return { e: lerp3(base.e, fe, w), c: lerp3(base.c, h, w), fov: lerp(base.fov, 42, w) };
}
function keyCam(p) {
  let i = 0; while (i < CK.length - 2 && CK[i + 1].p <= p) i++;
  const A = CK[i], Bk = CK[i + 1]; let f = (p - A.p) / (Bk.p - A.p);
  f = A.sc !== Bk.sc ? (p < CUT ? 0 : 1) : easeK(f);
  const a = A.cam, b = Bk.cam;
  const [r0, a0, l0] = sphOf(a[0], a[1]), [r1, a1, l1] = sphOf(b[0], b[1]);
  const da = ((a1 - a0 + Math.PI) % (2 * Math.PI) + 2 * Math.PI) % (2 * Math.PI) - Math.PI;
  const r = r0 * Math.pow(r1 / r0, f), az = a0 + da * f, el = l0 + (l1 - l0) * f, c = lerp3(a[1], b[1], f);
  return { e: [c[0] + r * Math.cos(el) * Math.sin(az), c[1] + r * Math.sin(el), c[2] + r * Math.cos(el) * Math.cos(az)], c, fov: lerp(a[2], b[2], f) };
}
// glowing heads on lines while they draw on
